param(
  [string]$Destination = (Join-Path $env:LOCALAPPDATA 'CodexComfyDirect'),
  [switch]$PrepareOnly,
  [switch]$ForcePortableRuntime,
  [switch]$NoConnect
)
$ErrorActionPreference = 'Stop'
function Get-ToolFile([string]$Uri, [string]$OutputFile) {
  $toolCurl = Get-Command curl.exe -ErrorAction SilentlyContinue
  if ($toolCurl) {
    & $toolCurl.Source --http1.1 --fail --location --retry 3 --connect-timeout 20 --max-time 600 --output $OutputFile $Uri
    if ($LASTEXITCODE -eq 0) { return }
  }
  Invoke-WebRequest -UseBasicParsing -Uri $Uri -OutFile $OutputFile
}
$toolRoot = [System.IO.Path]::GetFullPath($Destination)
$toolMarker = Join-Path $toolRoot '.codex-comfy-direct-managed'
if ((Test-Path -LiteralPath $toolRoot) -and (Get-ChildItem -LiteralPath $toolRoot -Force | Select-Object -First 1) -and -not (Test-Path -LiteralPath $toolMarker)) {
  throw '目标目录已有其他文件，已保留。请选择新的安装目录。'
}
New-Item -ItemType Directory -Path $toolRoot -Force | Out-Null
