$toolBytes = [Convert]::FromBase64String($toolPayload)
$toolHasher = [System.Security.Cryptography.SHA256]::Create()
try { $toolDigest = ([BitConverter]::ToString($toolHasher.ComputeHash($toolBytes))).Replace('-','').ToLowerInvariant() } finally { $toolHasher.Dispose() }
if ($toolDigest -ne 'c8d5c06d932f47479e0530f3aed6a670fd04c1076299b26fbff17c539cc9d422') { throw '安装包校验失败，未解压。' }
[System.IO.File]::WriteAllText($toolMarker, 'c8d5c06d932f47479e0530f3aed6a670fd04c1076299b26fbff17c539cc9d422')
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$toolMemory = New-Object System.IO.MemoryStream(,$toolBytes)
$toolZip = New-Object System.IO.Compression.ZipArchive($toolMemory)
try {
  foreach ($entry in $toolZip.Entries) {
    $target = [System.IO.Path]::GetFullPath((Join-Path $toolRoot $entry.FullName))
    if (-not $target.StartsWith($toolRoot.TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase)) { throw '压缩包包含异常路径。' }
    if ($entry.FullName.EndsWith('/')) { continue }
    New-Item -ItemType Directory -Path ([System.IO.Path]::GetDirectoryName($target)) -Force | Out-Null
    $sourceStream = $entry.Open()
    $targetStream = [System.IO.File]::Create($target)
    try { $sourceStream.CopyTo($targetStream) } finally { $sourceStream.Dispose(); $targetStream.Dispose() }
  }
} finally { $toolZip.Dispose(); $toolMemory.Dispose() }
[System.IO.File]::WriteAllText($toolMarker, 'c8d5c06d932f47479e0530f3aed6a670fd04c1076299b26fbff17c539cc9d422')
$toolNode = $null
$toolExisting = Get-Command node -ErrorAction SilentlyContinue
if ($toolExisting -and -not $ForcePortableRuntime) {
  try {
    $toolVersion = (& $toolExisting.Source --version).Trim().TrimStart('v')
    if ([Version]$toolVersion -ge [Version]'22.18.0') { $toolNode = $toolExisting.Source }
  } catch {}
}
if (-not $toolNode) {
  $toolRuntimeVersion = 'v24.22.2'
  $toolArch = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { 'arm64' } else { 'x64' }
  $toolArchiveName = "node-$toolRuntimeVersion-win-$toolArch.zip"
  $toolRuntimeDir = Join-Path $toolRoot 'runtime'
  New-Item -ItemType Directory -Path $toolRuntimeDir -Force | Out-Null
  $toolArchive = Join-Path $toolRuntimeDir $toolArchiveName
  $toolNode = Join-Path $toolRuntimeDir "node-$toolRuntimeVersion-win-$toolArch\node.exe"
  if (-not (Test-Path -LiteralPath $toolNode)) {
    $toolBase = "https://nodejs.org/dist/$toolRuntimeVersion"
    Write-Host '正在准备工具运行环境……'
    $toolSumsFile = Join-Path $toolRuntimeDir 'SHASUMS256.txt'
    Get-ToolFile "$toolBase/SHASUMS256.txt" $toolSumsFile
    $toolSums = [System.IO.File]::ReadAllText($toolSumsFile)
    $toolExpected = ($toolSums -split "`n" | Where-Object { $_ -match ('\s' + [regex]::Escape($toolArchiveName) + '\s*$') } | Select-Object -First 1).Trim().Split(' ')[0]
    if ($toolExpected -notmatch '^[0-9a-f]{64}$') { throw '未找到官方运行环境校验值。' }
    Get-ToolFile "$toolBase/$toolArchiveName" $toolArchive
    if ((Get-FileHash -LiteralPath $toolArchive -Algorithm SHA256).Hash.ToLowerInvariant() -ne $toolExpected) { throw '运行环境校验失败。' }
    Expand-Archive -LiteralPath $toolArchive -DestinationPath $toolRuntimeDir -Force
  }
}
& $toolNode --version
if ($LASTEXITCODE -ne 0) { throw '运行环境未能启动。' }
if ($PrepareOnly) { Write-Host "工具文件已准备：$toolRoot"; return }
& $toolNode (Join-Path $toolRoot 'bin.mjs') configure --wizard --register
if ($LASTEXITCODE -ne 0) { throw '连接信息或 Codex 配置未完成。' }
$toolCheckLog = Join-Path $toolRoot 'data\setup-check-error.log'
$toolHealth = & $toolNode (Join-Path $toolRoot 'bin.mjs') check 2> $toolCheckLog
if ($LASTEXITCODE -eq 0) { Write-Host '服务器接口已连通。' }
if ($LASTEXITCODE -ne 0 -and -not $NoConnect) {
  $toolBin = '"' + (Join-Path $toolRoot 'bin.mjs') + '"'
  Start-Process -FilePath $toolNode -ArgumentList @($toolBin,'connect') -WindowStyle Normal
  Write-Host '请在连接窗口按提示完成服务器登录，并保持该窗口打开。'
}
Write-Host '本地工具已配置。回到 Codex，重新加载 MCP 工具或在后续新聊天中使用 comfy_direct。没有提交视频生成。'
